export const meta = {
  name: 'go-dive-wave',
  description: 'Go research program phases 4+5 for one wave: sonnet deep dives per commissioned subtopic, pipelined into one opus consolidation (or revision) per group',
  phases: [
    { title: 'Dive', detail: 'one sonnet researcher per commissioned subtopic; each persists a cited artifact' },
    { title: 'Consolidate', detail: 'one opus consolidator or reviser per group; writes go-<group>.md', model: 'opus' },
  ],
}

// Generated by mkwave.py from a map or harvest receipt; the selection is baked in because args has a size cap.
const WAVE = __WAVE__
const DATE = '__DATE__'
const SELECTION = __SELECTION__
const ALREADY_LIST = __ALREADY__
const EXISTING = new Set(__EXISTING__)

const ROOT = '/home/mherwig/dev/grimoire-lore/.agents/worktrees/go'
const RESEARCH = ROOT + '/.agents/research'
const FRAME = RESEARCH + '/go-frame.md'
const MAP = RESEARCH + '/go-topic-map.md'
const EX = '/home/mherwig/.cache/research-lang/exemplars/go'
const RUN = '/home/mherwig/.cache/research-lang/go-tools/run.sh'
const FIX = '/home/mherwig/.cache/research-lang/go-tools/fixtures'
const ALREADY = ALREADY_LIST.map(s => '- ' + s).join('\n') || '- (nothing consolidated yet)'

const CONTEXT = `PROJECT CONTEXT (context for you, not content to reproduce):
- This is wave ${WAVE} of the research program that makes an AI-agent fleet expert in Go and its ecosystem (language as of Go 1.27, toolchain, modules, vet/staticcheck/golangci-lint, testing, concurrency and context, errors, the newer stdlib, performance tooling, security, release and distribution, Bazel for Go). Its output becomes AI-agent configuration (a glob-scoped go-quality rule with a support directory, a go-modules rule, one to three skills, a bundle, and a Go depth file for the published bazel-quality set) used by coding agents without a human in the loop, published through the lore catalog at ${ROOT} (a git worktree — treat it as the repository root; never cd to /home/mherwig/dev/grimoire-lore).
- Read the frame first (${FRAME}, including its Corrections), then the topic map (${MAP}): its "Conflicts resolved", "Artifact set decision" and the row(s) your brief cites. The map's decisions bind you; your job is depth, not re-deciding the artifact shape.
- THE FLEET HAS NO GO CODE. Evidence comes from the exemplar corpus of 35 upstream repositories under ${EX}/<owner>__<repo> (depth-1 clones with full source; kubernetes__kubernetes is config-only). The five audits under ${RESEARCH}/go-audit/ already measured them — cite the audits, and re-measure only what your brief needs. Cite <repo>@<sha12>:<path>:<line>.
- A REAL TOOLCHAIN is available: '${RUN} <cmd> [args]' runs Go 1.27.1 with staticcheck, golangci-lint v2.14.0, govulncheck, gofumpt, goimports, deadcode and modernize on PATH (caches on disk). Build planted fixtures — tiny throwaway modules — under ${FIX}/<your-slug>/ (never /tmp, never inside an exemplar clone) and RUN every verification you propose against a planted violation AND a compliant twin: a verification is only admissible if you watched it go red on the violation and stay green on the twin. Record the exact command, the exit code and the relevant output lines in the artifact. Never run writing commands (go mod tidy, go get, go fix -w, gofmt -w) inside an exemplar clone.
- Future consumers the artifacts must serve: a Go SDK wrapping the ocx CLI (mirroring /home/mherwig/dev/ocx-sdk-python), Go CLIs in the mould of the Rust repos /home/mherwig/dev/ocx and /home/mherwig/dev/grimoire (whose CLI contract is ${ROOT}/rules/rust-quality/cli-contract.md), and Go release artifacts the fleet mirrors. See go-audit/config-inventory.md.
- Sibling lore sets own Cargo/pyproject/package.json/JVM/docs/Bazel-core topics; a Bazel-Go dive covers rules_go/gazelle/nogo/go_deps only and defers bzlmod, hermeticity, caching, CI and flags to rules/bazel-quality/.
- Use read-only tools on every repository; the only files you may create or modify are your own OUTPUT FILE and your fixture directory. Date everything ${DATE}; version-tag every Go- or tool-version-specific claim.

ALREADY COVERED (do not re-tread; cite these consolidations' rule IDs instead):
${ALREADY}
`

const DIVE_CONTRACT = (path) => `OUTPUT FILE: ${path}
Write it with the Write tool; create parent directories as needed.

Structure, in this order:
1. YAML frontmatter: title, topic, agent (your label), model: sonnet, date_researched: ${DATE}, sources_count, fixtures (the fixture directory you used), scope (2-3 lines on what is and is not covered).
2. A table of contents.
3. "## Summary" — 10-20 bullet lines, each a standalone actionable claim.
4. "## Findings" — numbered subsections. EVERY non-obvious claim carries an inline citation as a markdown link to the exact URL read, or a repo@sha12:path:line into the exemplar corpus. Correct and incorrect Go side by side wherever a rule is easier shown than told. Exact package and function names, analyzer names, lint names and check IDs, flags, env vars, go.mod directives, command lines and numeric thresholds, with the Go or tool version they apply to.
5. "## Normative guidance candidates" — numbered, crisp, checkable imperative rules distilled from the findings, each with: the rule, a one-line rationale, how a reviewer VERIFIES it (an analyzer or lint name with the config that enables it, a go command, a grep with an explicit directory operand, or a named reading heuristic), and whether that verification was RUN against a planted violation (yes, with the fixture path / no, reading heuristic only). This is the section that matters most — make it dense and specific.
6. "## Verification runs" — for every runnable verification: fixture path, command, exit code on the violation, exit code on the compliant twin, the relevant output lines. A verification that did not go red is reported as such, with why.
7. "## Exemplar evidence" — which exemplars satisfy, violate or contradict each candidate, with repo@sha12:path:line (from the audits or your own re-measurement).
8. "## AI-agent angle" — what an LLM characteristically gets WRONG here (pre-generics and pre-1.22 idioms, io/ioutil, interface{}, pkg/errors, golang/mock, x/exp, hallucinated stdlib APIs, patterns that compile but are wrong) and the smallest mechanical check that catches each mistake.
9. "## Contested / evolving" — where practice genuinely disagrees or recently changed, and which way it is trending, as of when.
10. "## Sources" — table: URL | what it is | date/era | why worth reading. Minimum 12 distinct sources, at least 6 primary (go.dev docs, the spec, release notes, accepted proposals, the tool's own repository or docs, pkg.go.dev, talks).

Hard requirements:
- Call ToolSearch with query "select:WebSearch,WebFetch" FIRST to load the web tools, then research. For GitHub-hosted markdown prefer 'curl -sL https://raw.githubusercontent.com/...' through Bash so you read the whole file; pkg.go.dev and go.dev pages can be fetched with curl too.
- Actually FETCH the primary sources; never write from search snippets.
- Reflect current practice as of ${DATE} (Go 1.27); flag historical-only guidance with the version it stopped applying.
- No "it depends" without saying what it depends on.
- Verification commands you propose must follow this shape (a checker enforces it later): grep/rg always with an explicit directory operand ('.' at minimum) and -r where recursive; one -e per alternative instead of a pipe character inside a pattern; quote every --include glob ('--include=*.go' must be written --include='*.go'); never an unquoted '**'; no '$(...)' command substitution; no angle-bracket placeholders inside a search pattern; pipe into 'xargs -r'. Write the check so its OUTPUT is the violation (empty output = pass), and say so.
- Do not modify any file other than your output file and your fixture directory.`

const DIVE_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['path', 'sources_count', 'verifications_run', 'top_rules', 'surprises'],
  properties: {
    path: { type: 'string' },
    sources_count: { type: 'number' },
    verifications_run: { type: 'number', description: 'how many verifications were watched going red on a planted fixture' },
    top_rules: { type: 'array', items: { type: 'string' }, maxItems: 10 },
    surprises: { type: 'array', items: { type: 'string' }, maxItems: 6, description: 'findings the brief did not anticipate and that deserve their own round' },
  },
}

const CONSOLIDATE_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['path', 'rule_ids', 'conflicts_resolved', 'needs_another_round', 'must_count'],
  properties: {
    path: { type: 'string' },
    rule_ids: { type: 'array', items: { type: 'string' }, description: 'ID — imperative, one per rule' },
    conflicts_resolved: { type: 'array', items: { type: 'string' } },
    needs_another_round: { type: 'array', items: { type: 'string' }, description: 'subarea + the question, one per line' },
    must_count: { type: 'number' },
  },
}

function dive(item) {
  const path = RESEARCH + '/go-' + item.group + '/' + item.slug + '.md'
  return agent(
    `Model rationale: sonnet — online research, source digestion and fixture runs; volume work whose cost is in pages read and commands run, not in judgment.

${CONTEXT}

YOUR SUBAREA: ${item.label} (group: ${item.group_label}; rule family: ${item.id_family}; fixture dir: ${FIX}/${item.slug}/)

RESEARCH BRIEF (from the topic map; follow it exactly):
${item.brief}

${DIVE_CONTRACT(path)}

Return ONLY the structured receipt: the output path, source count, how many verifications you watched go red, your 8 strongest normative rules as one-liners, and up to 6 surprises.`,
    { label: 'dive:' + item.group + '/' + item.slug, phase: 'Dive', model: 'sonnet', effort: 'high', schema: DIVE_SCHEMA },
  )
}

function consolidate(group, items) {
  const path = RESEARCH + '/go-' + group + '.md'
  const dir = RESEARCH + '/go-' + group + '/'
  const families = [...new Set(items.map(i => i.id_family))]
  const family = families.join(' + ')
  const label = items[0].group_label
  const revise = EXISTING.has(group)
  const task = revise
    ? `You are REVISING an existing consolidated artifact to fold in a follow-up round it itself commissioned.

Read ${path} IN FULL, then every file in ${dir} in full — including the new artifact(s) this round produced: ${items.map(i => i.slug + '.md').join(', ')}.

Rewrite ${path} in place, preserving its structure:
- ID STABILITY IS A HARD CONTRACT. Every existing rule ID keeps its number and its meaning. Do not renumber, do not reorder into different IDs, do not reuse a retired number.
- New rules get NEW IDs continuing the sequence.
- If the follow-up CONTRADICTS an existing rule, change that rule's text in place and record the change — never leave both standing. A rule that overclaims a guarantee the new research shows does not exist is the most dangerous kind; fix it explicitly.
- A verification the new round watched FAIL to go red must be replaced or the rule demoted to a reading heuristic; record which.
- Update the Verdict for whatever the follow-up settled, and REMOVE from Open questions whatever it answered. Where the research established a GAP rather than an answer, move it into the Verdict as a documented gap.
- Add or extend a "## Revision log": one line per change — what, which IDs, why.
- Update the frontmatter's consolidates list and add a revised: ${DATE} key.`
    : `You are consolidating a topic into the single authoritative artifact a later author works from.

Read EVERY file in ${dir} (list it first; read each in full), plus the five audits under ${RESEARCH}/go-audit/ (at least the sections relevant to this group) and the topic map's rows for this group.

Write ${path}:
1. YAML frontmatter: title, topic, model: opus, id_family: ${families.join(', ')}, consolidates (the file list), date: ${DATE}.
2. "## Verdict" — 5-15 lines: the position this program takes, stated as DECISIONS, not as a survey. Where sub-researchers disagreed, decide and say why. Name the code kind each decision binds (library / SDK / CLI / service / test code) when it differs.
3. "## The ruleset" — merged, de-duplicated, numbered rules, one subsection per ID family this group owns (${families.join(', ')}). Each entry: ID (<FAMILY>-nn, e.g. GO-ERR-01), the rule as an imperative sentence, rationale (one line — the failure it prevents), verification (exact analyzer or lint with the config that enables it, go command, or grep with a directory operand; or a named reading heuristic), whether the verification was watched going red on a planted fixture (cite the dive's Verification runs), severity (MUST / SHOULD / CONSIDER), and the Go version floor it assumes if any. A MUST needs either a normative or measured source AND a verification that was run, or an explicit statement why it can only be a reading heuristic. Drop rules that are generic model common knowledge and would not change behaviour; keep the ones an agent gets wrong without being told. Smallest set with the highest yield. Group rows by the check that catches them.
4. "## Applied to the exemplars and the future consumers" — which rules the strict exemplars already satisfy, which prominent exemplars violate (repo@sha12:path:line from the audits or sub-artifacts), and which are new commitments for the Go SDK and Go CLIs.
5. "## AI-agent failure modes" — merged, ranked by how often it bites, each with the mechanical check.
6. "## Open questions" — what needs an owner decision (with the default the program will apply), and which subarea deserves ANOTHER research round (name the subarea and the question).
7. "## Sub-artifacts" — relative markdown links to each go-${group}/<file>.md with a one-line description.
8. "## Key sources" — the 10-15 best URLs across all sub-artifacts.

Merge rules: no claim without a citation that traces to a sub-artifact or a URL; no duplicated rules; prefer the more specific formulation; when two sub-artifacts conflict, state the conflict and resolve it with a reason. A consolidation with no resolved conflict and no "violated" row is a survey wearing a verdict's clothes — do not produce one.`

  return agent(
    `Model rationale: opus — synthesis across conflicting sources plus normative decisions that later become enforced rules.

${CONTEXT}

TOPIC: ${label} (family ${family})

${task}

You may re-run a sub-artifact's recorded verification with ${RUN} to settle a conflict. Do not modify any file other than ${path}.

Return ONLY the structured receipt: path, rule IDs with one-line imperatives, conflicts resolved, subareas needing another round, and the MUST count.`,
    { label: (revise ? 'revise:' : 'consolidate:') + group, phase: 'Consolidate', model: 'opus', effort: 'high', schema: CONSOLIDATE_SCHEMA },
  )
}

// ---------------------------------------------------------------- Run
const groups = {}
for (const item of SELECTION) (groups[item.group] = groups[item.group] || []).push(item)
const entries = Object.entries(groups)
log('Wave ' + WAVE + ': ' + SELECTION.length + ' dives across ' + entries.length + ' groups (' + entries.map(([g, i]) => g + 'x' + i.length).join(', ') + '); revising: ' + (entries.filter(([g]) => EXISTING.has(g)).map(([g]) => g).join(', ') || 'none'))

const results = await pipeline(
  entries,
  ([group, items]) => parallel(items.map(item => () => dive(item).then(r => ({ slug: item.slug, ...(r || {}), ok: !!r })))),
  (dives, [group, items]) => {
    const ok = dives.filter(Boolean).filter(d => d.ok)
    if (!ok.length) { log('SKIP consolidate:' + group + ' — every dive dropped'); return { group, dives, consolidation: null } }
    if (ok.length < items.length) log('consolidate:' + group + ' proceeding with ' + ok.length + '/' + items.length + ' dives')
    return consolidate(group, items).then(c => ({ group, dives, consolidation: c }))
  },
)

const out = results.filter(Boolean)
const surprises = out.flatMap(r => (r.dives || []).filter(Boolean).flatMap(d => (d.surprises || []).map(s => r.group + '/' + d.slug + ': ' + s)))
const another = out.flatMap(r => ((r.consolidation && r.consolidation.needs_another_round) || []).map(s => r.group + ': ' + s))
const musts = out.reduce((n, r) => n + ((r.consolidation && r.consolidation.must_count) || 0), 0)
log('Wave ' + WAVE + ' done: ' + out.length + '/' + entries.length + ' groups consolidated · ' + musts + ' MUST rules · ' + surprises.length + ' surprises · ' + another.length + ' follow-ups')
return { wave: WAVE, groups: out, surprises, needs_another_round: another, must_count: musts }
